import Foundation

/// One verse (or short passage) shown for a day.
public struct DailyVerse: Codable, Hashable, Sendable {
    public let reference: String
    public let text: String

    public init(reference: String, text: String) {
        self.reference = reference
        self.text = text
    }

    /// "“For God so loved…” — John 3:16 (BSB)", for sharing.
    public var shareText: String { "\(text)\n— \(reference) (BSB)" }
}

/// The bundled list of daily verses (Berean Standard Bible, public domain).
///
/// The list is generated by `scripts/build_daily_verses.py` straight from the
/// publisher's files, so the wording is exact. Each calendar day maps to the
/// next verse in the list, so everyone sees the same verse all day and a new
/// one tomorrow; after the last verse it starts over.
public struct VerseLibrary: Sendable {
    public let translation: String
    public let verses: [DailyVerse]

    public init(translation: String, verses: [DailyVerse]) {
        self.translation = translation
        self.verses = verses
    }

    private struct File: Decodable {
        let translation: String
        let verses: [DailyVerse]
    }

    /// Loads the list shipped inside the app.
    public static func bundled() throws -> VerseLibrary {
        guard let url = Bundle.module.url(forResource: "daily-verses", withExtension: "json") else {
            throw CocoaError(.fileNoSuchFile)
        }
        let file = try JSONDecoder().decode(File.self, from: Data(contentsOf: url))
        return VerseLibrary(translation: file.translation, verses: file.verses)
    }

    /// Position in the list for `date`'s calendar day.
    public func index(for date: Date, calendar: Calendar) -> Int {
        guard !verses.isEmpty else { return 0 }
        let start = calendar.date(from: DateComponents(year: 2026, month: 1, day: 1)) ?? Date(timeIntervalSince1970: 0)
        let days = calendar.dateComponents([.day], from: calendar.startOfDay(for: start), to: calendar.startOfDay(for: date)).day ?? 0
        let count = verses.count
        return ((days % count) + count) % count
    }

    public func verse(for date: Date, calendar: Calendar) -> DailyVerse? {
        verses.isEmpty ? nil : verses[index(for: date, calendar: calendar)]
    }
}
